// <PopoverFeedback flagKey="my-flag" prompt="How do you feel?" icons="thumbs" ldClient={ldClient} />
// <PopoverFeedback flagKey="my-flag" prompt="How do you feel?" icons="smileys" ldClient={ldClient} />
