// Session replay import — remove this line if @launchdarkly/session-replay is not installed
import { LDRecord } from "@launchdarkly/session-replay";
import type { LDClient } from "launchdarkly-js-client-sdk";

export type LDFeedbackData = {
  feedback_answer: string;
  flag_key: string;
  sentiment?: LDFeedbackSentiment;
  feedback_prompt?: string;
  o11y_session_id?: string;
  custom_properties?: Record<string, any>;
};

export type LDFeedbackSentiment = "positive" | "neutral" | "negative";

export function sendFeedback(
  client: LDClient,
  flagKey: string,
  feedback: string,
  sentiment?: LDFeedbackSentiment,
  prompt?: string,
  customProperties?: Record<string, any>,
) {
  const feedbackData: LDFeedbackData = {
    feedback_answer: feedback,
    flag_key: flagKey,
    sentiment: sentiment ?? "neutral",
    custom_properties: customProperties,
  };

  // Session replay — remove this block if @launchdarkly/session-replay is not installed
  const sessionID = LDRecord?.getSession()?.sessionSecureID;
  if (sessionID) {
    feedbackData.o11y_session_id = sessionID;
  }

  if (prompt) {
    feedbackData.feedback_prompt = prompt;
  }

  client.track("$ld:feedback", feedbackData);
  client.flush();
}

# SDK Track Patterns

How to call `track()` in each LaunchDarkly SDK. Use this reference to match the patterns already in use in the codebase — and to add the right call when starting fresh.

The key distinction across all SDKs: **server-side SDKs require a context per call; client-side SDKs do not.**

---

## JavaScript / TypeScript — Node.js (Server-side)

**Package:** `@launchdarkly/node-server-sdk` (v9+) or `launchdarkly-node-server-sdk` (v6–v8)

```bash
npm install @launchdarkly/node-server-sdk
```

```typescript
import * as ld from '@launchdarkly/node-server-sdk';

const client = ld.init(process.env.LD_SDK_KEY!);
await client.waitForInitialization();

// Count / occurrence metric (no metricValue)
client.track('checkout-completed', context);

// Value metric — pass the measurement as metricValue
